package generator

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/AlexGromer/deckhouse-helm-generator/pkg/types"
)

// OutputFile represents a single file to be written.
type OutputFile struct {
	RelPath string
	Content []byte
	Mode    os.FileMode
}

// OutputSet is a collection of files generated by a chart generation process.
type OutputSet struct {
	Files []OutputFile
}

// NewOutputSet creates a new OutputSet.
func NewOutputSet() *OutputSet {
	return &OutputSet{}
}

// ByPath returns a map of file paths to their content.
func (s *OutputSet) ByPath() map[string][]byte {
	m := make(map[string][]byte, len(s.Files))
	for _, f := range s.Files {
		m[f.RelPath] = f.Content
	}
	return m
}

// Add adds a file to the set, normalizing the path. Returns an error if the path already exists with different content.
func (s *OutputSet) Add(path string, content []byte, mode os.FileMode) error {
	relPath := filepath.ToSlash(filepath.Clean(path))
	if strings.HasPrefix(relPath, "../") || relPath == ".." || relPath == "." {
		return fmt.Errorf("invalid output path: %s", path)
	}

	for _, f := range s.Files {
		if f.RelPath == relPath {
			if string(f.Content) != string(content) {
				return fmt.Errorf("duplicate output path %s with different content", relPath)
			}
			return nil
		}
	}

	s.Files = append(s.Files, OutputFile{
		RelPath: relPath,
		Content: content,
		Mode:    mode,
	})
	return nil
}

// Write writes the files in the set to the specified root directory.
func (s *OutputSet) Write(root string) error {
	sort.Slice(s.Files, func(i, j int) bool {
		return s.Files[i].RelPath < s.Files[j].RelPath
	})

	for _, f := range s.Files {
		fullPath := filepath.Join(root, f.RelPath)
		if err := os.MkdirAll(filepath.Dir(fullPath), 0755); err != nil {
			return err
		}
		if err := os.WriteFile(fullPath, f.Content, f.Mode); err != nil {
			return err
		}
	}
	return nil
}

// RenderChartOutput renders a single chart to an OutputSet.
func RenderChartOutput(chart *types.GeneratedChart) (*OutputSet, error) {
	set := NewOutputSet()
	prefix := ""
	if chart.Name != "" {
		prefix = chart.Name + "/"
	}

	if err := set.Add(prefix+".helmignore", []byte(helmIgnoreContent), 0644); err != nil {
		return nil, err
	}

	if chart.ChartYAML != "" {
		if err := set.Add(prefix+"Chart.yaml", []byte(chart.ChartYAML), 0644); err != nil {
			return nil, err
		}
	}

	if chart.ValuesYAML != "" {
		if err := set.Add(prefix+"values.yaml", []byte(chart.ValuesYAML), 0644); err != nil {
			return nil, err
		}
	}

	if chart.ValuesSchema != "" {
		if err := set.Add(prefix+"values.schema.json", []byte(chart.ValuesSchema), 0644); err != nil {
			return nil, err
		}
	}

	if chart.Helpers != "" {
		if err := set.Add(prefix+"templates/_helpers.tpl", []byte(chart.Helpers), 0644); err != nil {
			return nil, err
		}
	}

	if chart.Notes != "" {
		if err := set.Add(prefix+"templates/NOTES.txt", []byte(chart.Notes), 0644); err != nil {
			return nil, err
		}
	}

	for path, content := range chart.Templates {
		if err := set.Add(prefix+path, []byte(content), 0644); err != nil {
			return nil, err
		}
	}

	for _, file := range chart.ExternalFiles {
		fullPath := filepath.ToSlash(filepath.Clean(prefix + file.Path))
		if strings.HasPrefix(fullPath, "../") {
			return nil, fmt.Errorf("outside chart directory: %s", file.Path)
		}

		mode := os.FileMode(0644)
		if strings.HasSuffix(file.Path, ".sh") {
			mode = 0755
		}

		if err := set.Add(fullPath, []byte(file.Content), mode); err != nil {
			return nil, err
		}
	}

	return set, nil
}

const helmIgnoreContent = `# Patterns to ignore when building packages.
# This supports shell glob matching, relative path matching, and
# negation (prefixed with !). Only one pattern per line.
.DS_Store
# Common VCS dirs
.git/
.gitignore
.bzr/
.bzrignore
.hg/
.hgignore
.svn/
# Common backup files
*.swp
*.bak
*.tmp
*.orig
*~
# Various IDEs
.project
.idea/
*.tmproj
.vscode/
`

// RenderOutputSet renders multiple charts and other files to an OutputSet based on the generation mode.
func RenderOutputSet(charts []*types.GeneratedChart, mode types.OutputMode, chartName string) (*OutputSet, error) {
	set := NewOutputSet()
	for _, chart := range charts {
		chartSet, err := RenderChartOutput(chart)
		if err != nil {
			return nil, err
		}
		for _, f := range chartSet.Files {
			if err := set.Add(f.RelPath, f.Content, f.Mode); err != nil {
				return nil, err
			}
		}
	}
	return set, nil
}

// Get returns a file by relative path.
func (s *OutputSet) Get(relPath string) (*OutputFile, bool) {
	for i := range s.Files {
		if s.Files[i].RelPath == relPath {
			return &s.Files[i], true
		}
	}
	return nil, false
}

// Paths returns sorted relative paths of all files in the set.
func (s *OutputSet) Paths() []string {
	paths := make([]string, len(s.Files))
	for i, f := range s.Files {
		paths[i] = f.RelPath
	}
	sort.Strings(paths)
	return paths
}

// Len returns the number of files in the set.
func (s *OutputSet) Len() int {
	return len(s.Files)
}

// ChartFiles returns files filtered by a chart directory prefix.
func (s *OutputSet) ChartFiles(chartDir string) []OutputFile {
	var files []OutputFile
	prefix := chartDir
	if prefix != "" && !strings.HasSuffix(prefix, "/") {
		prefix += "/"
	}
	for _, f := range s.Files {
		if prefix == "" || strings.HasPrefix(f.RelPath, prefix) {
			files = append(files, f)
		}
	}
	return files
}
